import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { 
  getProductById, 
  getProducts, 
  addToCart, 
  toggleWishlist,
  getProductQuestions,
  askQuestion,
  answerQuestion,
  deleteQuestion
} from '../services/api';
import { isAuthenticated } from '../util/auth';
import useToast from '../hooks/useToast';
import { useCart } from '../context/CartContext';
import { useTheme } from '../context/ThemeContext';

const ProductDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [product, setProduct] = useState(null);
  const [relatedProducts, setRelatedProducts] = useState([]);
  const [similarProducts, setSimilarProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [quantity, setQuantity] = useState(1);
  const [selectedImage, setSelectedImage] = useState(0);
  const [activeTab, setActiveTab] = useState('description');
  const [isWishlisted, setIsWishlisted] = useState(false);
  const [wishlistLoading, setWishlistLoading] = useState(false);
  const [showShareModal, setShowShareModal] = useState(false);
  const [showSubscriptionModal, setShowSubscriptionModal] = useState(false);
  const [subscriptionFrequency, setSubscriptionFrequency] = useState('weekly');
  const [questions, setQuestions] = useState([]);
  const [newQuestion, setNewQuestion] = useState('');
  const [answerText, setAnswerText] = useState({});
  const [showAnswerForm, setShowAnswerForm] = useState({});
  const [qaLoading, setQaLoading] = useState(false);
  const { showSuccessToast, showErrorToast } = useToast();
  const { updateCartCount } = useCart();
  const { isDarkMode } = useTheme();

  // Construct product images array
  const productImages = React.useMemo(() => {
    if (!product) return [];
    const images = [];
    if (product.image) images.push(product.image);
    if (product.images && Array.isArray(product.images)) {
      images.push(...product.images.filter(img => img && img !== product.image));
    }
    console.log('Product images:', images);
    return images;
  }, [product]);

  useEffect(() => {
    fetchProduct();
    fetchRelatedProducts();
  }, [id]);

  useEffect(() => {
    if (product) {
      fetchSimilarProducts();
      fetchQuestions();
    }
  }, [product]);

  const fetchProduct = async () => {
    try {
      setLoading(true);
      const res = await getProductById(id);
      setProduct(res.data);
      if (res.data.images && res.data.images.length > 0) {
        setSelectedImage(0);
      }
    } catch (error) {
      console.error('Error fetching product:', error);
      showErrorToast('Failed to load product details');
    } finally {
      setLoading(false);
    }
  };

  const fetchRelatedProducts = async () => {
    try {
      const res = await getProducts();
      setRelatedProducts(res.data.products.filter(p => p._id !== id).slice(0, 4));
    } catch (error) {
      console.error('Error fetching related products:', error);
    }
  };

  const fetchSimilarProducts = async () => {
    try {
      const res = await getProducts('', '', 1);
      setSimilarProducts(res.data.products.filter(p => p.category === product?.category && p._id !== id).slice(0, 6));
    } catch (error) {
      console.error('Error fetching similar products:', error);
    }
  };

  const handleAddToCart = async () => {
    if (!isAuthenticated()) {
      navigate('/login');
      return;
    }

    if (product.stock === 0) {
      showErrorToast('Product is out of stock');
      return;
    }

    try {
      await addToCart(product._id, quantity);
      updateCartCount();
      showSuccessToast(`${product.name} added to cart!`);
    } catch (error) {
      console.error('Error adding to cart:', error);
      showErrorToast('Failed to add to cart');
    }
  };

  const handleToggleWishlist = async () => {
    if (!isAuthenticated()) {
      navigate('/login');
      return;
    }
    try {
      setWishlistLoading(true);
      await toggleWishlist(product._id);
      setIsWishlisted(!isWishlisted);
      showSuccessToast(isWishlisted ? 'Removed from wishlist' : 'Added to wishlist');
    } catch (error) {
      console.error('Wishlist error:', error);
      showErrorToast('Failed to update wishlist');
    } finally {
      setWishlistLoading(false);
    }
  };

  const handleShare = (platform) => {
    const shareUrl = window.location.href;
    const shareText = `Check out ${product.name} on MilkMitra!`;
    let url = '';

    switch (platform) {
      case 'whatsapp':
        url = `https://wa.me/?text=${encodeURIComponent(shareText + ' ' + shareUrl)}`;
        break;
      case 'facebook':
        url = `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(shareUrl)}`;
        break;
      case 'twitter':
        url = `https://twitter.com/intent/tweet?text=${encodeURIComponent(shareText)}&url=${encodeURIComponent(shareUrl)}`;
        break;
      case 'copy':
        navigator.clipboard.writeText(shareUrl);
        showSuccessToast('Link copied to clipboard!');
        setShowShareModal(false);
        return;
      default:
        return;
    }
    window.open(url, '_blank', 'width=600,height=400');
    setShowShareModal(false);
  };

  const handleSubscribe = async () => {
    if (!isAuthenticated()) {
      navigate('/login');
      return;
    }
    // Subscription logic would go here
    showSuccessToast(`Subscription created for ${subscriptionFrequency} delivery!`);
    setShowSubscriptionModal(false);
  };

  const getBulkDiscount = (qty) => {
    if (qty >= 10) return 0.15; // 15% discount for 10+ items
    if (qty >= 5) return 0.10; // 10% discount for 5+ items
    if (qty >= 3) return 0.05; // 5% discount for 3+ items
    return 0;
  };

  const getCategoryEmoji = (category) => {
    const emojis = {
      milk: '🥛',
      ghee: '🍯',
      cheese: '🧀',
      butter: '🧈',
      curd: '🥣',
      paneer: '🧊',
      cream: '🍦',
      yogurt: '🍶',
      lassi: '🥤',
      buttermilk: '🫙'
    };
    return emojis[category] || '🥛';
  };

  const getCategoryGradient = (category) => {
    const gradients = {
      milk: 'from-blue-200 to-blue-400 dark:from-blue-800 dark:to-blue-600',
      ghee: 'from-amber-200 to-amber-400 dark:from-amber-800 dark:to-amber-600',
      cheese: 'from-yellow-200 to-yellow-400 dark:from-yellow-800 dark:to-yellow-600',
      butter: 'from-orange-200 to-orange-400 dark:from-orange-800 dark:to-orange-600',
      curd: 'from-green-200 to-green-400 dark:from-green-800 dark:to-green-600',
      paneer: 'from-purple-200 to-purple-400 dark:from-purple-800 dark:to-purple-600',
      cream: 'from-pink-200 to-pink-400 dark:from-pink-800 dark:to-pink-600',
      yogurt: 'from-teal-200 to-teal-400 dark:from-teal-800 dark:to-teal-600',
      lassi: 'from-cyan-200 to-cyan-400 dark:from-cyan-800 dark:to-cyan-600',
      buttermilk: 'from-lime-200 to-lime-400 dark:from-lime-800 dark:to-lime-600'
    };
    return gradients[category] || 'from-gray-200 to-gray-400 dark:from-gray-700 dark:to-gray-500';
  };

  const renderStars = (rating) => {
    const stars = [];
    for (let i = 1; i <= 5; i++) {
      if (i <= rating) {
        stars.push(<span key={i} className="text-yellow-400">★</span>);
      } else if (i - 0.5 <= rating) {
        stars.push(<span key={i} className="text-yellow-400">★</span>);
      } else {
        stars.push(<span key={i} className="text-gray-300">★</span>);
      }
    }
    return stars;
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 dark:from-gray-900 dark:to-gray-800 flex items-center justify-center">
        <div className="relative">
          <div className="w-16 h-16 border-4 border-primary-200 border-t-primary-600 rounded-full animate-spin"></div>
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="w-8 h-8 bg-gradient-to-br from-primary-500 to-secondary-500 rounded-full animate-pulse"></div>
          </div>
        </div>
      </div>
    );
  }

  if (!product) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 dark:from-gray-900 dark:to-gray-800 flex items-center justify-center">
        <div className="text-center">
          <h2 className="text-2xl font-bold text-gray-800 dark:text-white mb-4">Product not found</h2>
          <Link to="/products" className="text-primary-600 hover:text-primary-700">Back to Products</Link>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 dark:from-gray-900 dark:to-gray-800">
      <div className="max-w-7xl mx-auto px-4 py-8">
        {/* Breadcrumb */}
        <nav className="mb-8">
          <ol className="flex items-center space-x-2 text-sm">
            <li><Link to="/" className="text-primary-600 hover:text-primary-700">Home</Link></li>
            <li className="text-gray-400">/</li>
            <li><Link to="/products" className="text-primary-600 hover:text-primary-700">Products</Link></li>
            <li className="text-gray-400">/</li>
            <li className="text-gray-600 dark:text-gray-300">{product.name}</li>
          </ol>
        </nav>

        {/* Main Product Section */}
        <div className={`rounded-3xl p-8 shadow-xl mb-8 ${isDarkMode ? 'bg-gray-800/50 backdrop-blur-xl border border-white/10' : 'bg-white/70 backdrop-blur-xl border border-gray-200'}`}>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
            {/* Product Images */}
            <div className="space-y-4">
              {/* Main Image */}
              <div className={`relative aspect-square rounded-2xl overflow-hidden bg-gradient-to-br ${getCategoryGradient(product.category)} shadow-inner`}>
                {productImages && productImages.length > 0 && productImages[selectedImage] ? (
                  <img
                    src={productImages[selectedImage]}
                    alt={product.name}
                    className="w-full h-full object-cover"
                    onError={(e) => {
                      e.target.style.display = 'none';
                      e.target.parentElement.querySelector('.fallback-emoji').style.display = 'flex';
                    }}
                  />
                ) : null}
                <div className="fallback-emoji w-full h-full flex items-center justify-center absolute inset-0" style={{ display: (!productImages || productImages.length === 0 || !productImages[selectedImage]) ? 'flex' : 'none' }}>
                  <span className="text-8xl">{getCategoryEmoji(product.category)}</span>
                </div>
              </div>

              {/* Thumbnail Images */}
              {productImages.length > 1 && (
                <div className="flex space-x-3">
                  {productImages.map((img, idx) => (
                    <button
                      key={idx}
                      onClick={() => setSelectedImage(idx)}
                      className={`w-20 h-20 rounded-xl overflow-hidden border-2 transition-all ${
                        selectedImage === idx 
                          ? 'border-primary-500 scale-110' 
                          : 'border-gray-300 dark:border-gray-600 hover:border-primary-300'
                      }`}
                    >
                      <img src={img} alt={`${product.name} ${idx + 1}`} className="w-full h-full object-cover" />
                    </button>
                  ))}
                </div>
              )}
            </div>

            {/* Product Info */}
            <div className="space-y-6">
              {/* Category Badge */}
              <span className={`inline-block px-4 py-2 text-sm font-bold rounded-full bg-gradient-to-r ${getCategoryGradient(product.category)} text-white`}>
                {getCategoryEmoji(product.category)} {product.category}
              </span>

              {/* Product Name */}
              <h1 className="text-4xl font-bold text-gray-800 dark:text-white capitalize">
                {product.name}
              </h1>

              {/* Brand */}
              {product.brand && (
                <p className="text-gray-600 dark:text-gray-400">
                  Brand: <span className="font-semibold">{product.brand}</span>
                </p>
              )}

              {/* Rating */}
              <div className="flex items-center space-x-2">
                <div className="flex">{renderStars(product.ratings)}</div>
                <span className="text-gray-600 dark:text-gray-400">
                  ({product.numReviews} {product.numReviews === 1 ? 'review' : 'reviews'})
                </span>
              </div>

              {/* Price */}
              <div className="flex items-baseline space-x-3">
                <span className="text-4xl font-bold text-primary-600 dark:text-primary-400">
                  ₹{product.price}
                </span>
                <span className="text-lg text-gray-600 dark:text-gray-400">
                  /{product.unit}
                </span>
              </div>

              {/* Stock Status */}
              <div className={`inline-flex items-center px-4 py-2 rounded-full font-medium ${
                product.stock > 10 
                  ? 'bg-green-100 text-green-700 dark:bg-green-900/50 dark:text-green-300' 
                  : product.stock > 0 
                    ? 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/50 dark:text-yellow-300'
                    : 'bg-red-100 text-red-700 dark:bg-red-900/50 dark:text-red-300'
              }`}>
                {product.stock > 0 ? `${product.stock} in stock` : 'Out of Stock'}
              </div>

              {/* Quantity Selector */}
              <div className="flex items-center space-x-4">
                <label className="font-semibold text-gray-800 dark:text-white">Quantity:</label>
                <div className="flex items-center border-2 border-gray-300 dark:border-gray-600 rounded-xl overflow-hidden">
                  <button
                    onClick={() => setQuantity(Math.max(1, quantity - 1))}
                    className="w-12 h-12 flex items-center justify-center text-gray-600 dark:text-gray-300 hover:bg-primary-500 hover:text-white transition-colors font-bold"
                  >
                    -
                  </button>
                  <span className="w-16 text-center font-bold text-gray-800 dark:text-white">{quantity}</span>
                  <button
                    onClick={() => setQuantity(Math.min(product.stock, quantity + 1))}
                    className="w-12 h-12 flex items-center justify-center text-gray-600 dark:text-gray-300 hover:bg-primary-500 hover:text-white transition-colors font-bold"
                  >
                    +
                  </button>
                </div>
              </div>

              {/* Action Buttons */}
              <div className="flex space-x-4">
                <button
                  onClick={handleAddToCart}
                  disabled={product.stock === 0}
                  className={`flex-1 font-bold py-4 rounded-xl transform transition-all duration-300 hover:scale-105 shadow-lg hover:shadow-xl disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none ${
                    product.stock === 0 
                      ? 'bg-gray-400 text-gray-200 cursor-not-allowed'
                      : 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white hover:from-primary-600 hover:to-secondary-600'
                  }`}
                >
                  {product.stock === 0 ? 'Out of Stock' : 'Add to Cart'}
                </button>
                <button
                  onClick={handleToggleWishlist}
                  disabled={wishlistLoading}
                  className={`px-6 py-4 rounded-xl font-bold border-2 transition-all duration-300 ${
                    isWishlisted
                      ? 'border-red-500 text-red-500 bg-red-50 dark:bg-red-900/20'
                      : 'border-gray-300 dark:border-gray-600 text-gray-600 dark:text-gray-400 hover:border-red-300 hover:text-red-500'
                  }`}
                >
                  {wishlistLoading ? '...' : isWishlisted ? '♥ Wishlisted' : '♡ Wishlist'}
                </button>
                <button
                  onClick={() => setShowShareModal(true)}
                  className="px-6 py-4 rounded-xl font-bold border-2 border-gray-300 dark:border-gray-600 text-gray-600 dark:text-gray-400 hover:border-primary-300 hover:text-primary-500 transition-all duration-300"
                >
                  Share
                </button>
              </div>

              {/* Subscription Option */}
              <div className={`p-4 rounded-xl ${isDarkMode ? 'bg-gray-700/50' : 'bg-gray-50'}`}>
                <div className="flex items-center justify-between mb-3">
                  <h3 className="font-semibold text-gray-800 dark:text-white">📦 Subscribe & Save</h3>
                  <button
                    onClick={() => setShowSubscriptionModal(true)}
                    className="text-sm text-primary-600 dark:text-primary-400 font-medium hover:underline"
                  >
                    Setup Subscription
                  </button>
                </div>
                <p className="text-sm text-gray-600 dark:text-gray-400">Get regular deliveries and save up to 15%!</p>
              </div>

              {/* Bulk Discount Pricing */}
              {quantity > 1 && (
                <div className={`p-4 rounded-xl ${isDarkMode ? 'bg-gray-700/50' : 'bg-gray-50'}`}>
                  <h3 className="font-semibold text-gray-800 dark:text-white mb-3">💰 Bulk Discount</h3>
                  <div className="space-y-2 text-sm">
                    <div className={`flex justify-between ${quantity >= 3 ? 'text-green-600 dark:text-green-400 font-bold' : 'text-gray-600 dark:text-gray-400'}`}>
                      <span>3+ items:</span>
                      <span>5% off</span>
                    </div>
                    <div className={`flex justify-between ${quantity >= 5 ? 'text-green-600 dark:text-green-400 font-bold' : 'text-gray-600 dark:text-gray-400'}`}>
                      <span>5+ items:</span>
                      <span>10% off</span>
                    </div>
                    <div className={`flex justify-between ${quantity >= 10 ? 'text-green-600 dark:text-green-400 font-bold' : 'text-gray-600 dark:text-gray-400'}`}>
                      <span>10+ items:</span>
                      <span>15% off</span>
                    </div>
                    {getBulkDiscount(quantity) > 0 && (
                      <div className="mt-3 pt-3 border-t border-gray-300 dark:border-gray-600">
                        <span className="text-green-600 dark:text-green-400 font-bold">
                          You save: ₹{(product.price * quantity * getBulkDiscount(quantity)).toFixed(2)}
                        </span>
                      </div>
                    )}
                  </div>
                </div>
              )}

              {/* Product Highlights */}
              <div className={`p-4 rounded-xl ${isDarkMode ? 'bg-gray-700/50' : 'bg-gray-50'}`}>
                <h3 className="font-semibold text-gray-800 dark:text-white mb-3">Product Highlights:</h3>
                <ul className="space-y-2 text-gray-600 dark:text-gray-400">
                  <li className="flex items-center">
                    <span className="text-green-500 mr-2">✓</span>
                    Premium quality dairy product
                  </li>
                  <li className="flex items-center">
                    <span className="text-green-500 mr-2">✓</span>
                    Fresh and hygienically packed
                  </li>
                  <li className="flex items-center">
                    <span className="text-green-500 mr-2">✓</span>
                    Farm to table freshness
                  </li>
                  <li className="flex items-center">
                    <span className="text-green-500 mr-2">✓</span>
                    No preservatives added
                  </li>
                </ul>
              </div>
            </div>
          </div>
        </div>

        {/* Product Details Tabs */}
        <div className={`rounded-3xl p-8 shadow-xl mb-8 ${isDarkMode ? 'bg-gray-800/50 backdrop-blur-xl border border-white/10' : 'bg-white/70 backdrop-blur-xl border border-gray-200'}`}>
          <div className="flex flex-wrap gap-2 mb-6 border-b border-gray-200 dark:border-gray-700">
            <button
              onClick={() => setActiveTab('description')}
              className={`pb-4 px-4 font-semibold transition-colors ${
                activeTab === 'description'
                  ? 'text-primary-600 border-b-2 border-primary-600 dark:text-primary-400'
                  : 'text-gray-600 dark:text-gray-400 hover:text-gray-800 dark:hover:text-gray-200'
              }`}
            >
              Description
            </button>
            <button
              onClick={() => setActiveTab('specifications')}
              className={`pb-4 px-4 font-semibold transition-colors ${
                activeTab === 'specifications'
                  ? 'text-primary-600 border-b-2 border-primary-600 dark:text-primary-400'
                  : 'text-gray-600 dark:text-gray-400 hover:text-gray-800 dark:hover:text-gray-200'
              }`}
            >
              Specifications
            </button>
            <button
              onClick={() => setActiveTab('nutritional')}
              className={`pb-4 px-4 font-semibold transition-colors ${
                activeTab === 'nutritional'
                  ? 'text-primary-600 border-b-2 border-primary-600 dark:text-primary-400'
                  : 'text-gray-600 dark:text-gray-400 hover:text-gray-800 dark:hover:text-gray-200'
              }`}
            >
              Nutritional Info
            </button>
            <button
              onClick={() => setActiveTab('reviews')}
              className={`pb-4 px-4 font-semibold transition-colors ${
                activeTab === 'reviews'
                  ? 'text-primary-600 border-b-2 border-primary-600 dark:text-primary-400'
                  : 'text-gray-600 dark:text-gray-400 hover:text-gray-800 dark:hover:text-gray-200'
              }`}
            >
              Reviews ({product.numReviews})
            </button>
            <button
              onClick={() => setActiveTab('qa')}
              className={`pb-4 px-4 font-semibold transition-colors ${
                activeTab === 'qa'
                  ? 'text-primary-600 border-b-2 border-primary-600 dark:text-primary-400'
                  : 'text-gray-600 dark:text-gray-400 hover:text-gray-800 dark:hover:text-gray-200'
              }`}
            >
              Q&A
            </button>
            <button
              onClick={() => setActiveTab('delivery')}
              className={`pb-4 px-4 font-semibold transition-colors ${
                activeTab === 'delivery'
                  ? 'text-primary-600 border-b-2 border-primary-600 dark:text-primary-400'
                  : 'text-gray-600 dark:text-gray-400 hover:text-gray-800 dark:hover:text-gray-200'
              }`}
            >
              Delivery Info
            </button>
            <button
              onClick={() => setActiveTab('return')}
              className={`pb-4 px-4 font-semibold transition-colors ${
                activeTab === 'return'
                  ? 'text-primary-600 border-b-2 border-primary-600 dark:text-primary-400'
                  : 'text-gray-600 dark:text-gray-400 hover:text-gray-800 dark:hover:text-gray-200'
              }`}
            >
              Return Policy
            </button>
          </div>

          {activeTab === 'description' && (
            <div className="prose max-w-none">
              <p className="text-gray-700 dark:text-gray-300 leading-relaxed text-lg">
                {product.description}
              </p>
            </div>
          )}

          {activeTab === 'specifications' && (
            <div className={`p-6 rounded-xl ${isDarkMode ? 'bg-gray-700/50' : 'bg-gray-50'}`}>
              <h3 className="font-semibold text-gray-800 dark:text-white mb-4">Product Specifications</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="flex justify-between py-2 border-b border-gray-200 dark:border-gray-600">
                  <span className="text-gray-600 dark:text-gray-400">Category:</span>
                  <span className="font-semibold text-gray-800 dark:text-white capitalize">{product.category}</span>
                </div>
                <div className="flex justify-between py-2 border-b border-gray-200 dark:border-gray-600">
                  <span className="text-gray-600 dark:text-gray-400">Brand:</span>
                  <span className="font-semibold text-gray-800 dark:text-white">{product.brand || 'MilkMitra'}</span>
                </div>
                <div className="flex justify-between py-2 border-b border-gray-200 dark:border-gray-600">
                  <span className="text-gray-600 dark:text-gray-400">Unit:</span>
                  <span className="font-semibold text-gray-800 dark:text-white">{product.unit}</span>
                </div>
                <div className="flex justify-between py-2 border-b border-gray-200 dark:border-gray-600">
                  <span className="text-gray-600 dark:text-gray-400">Stock:</span>
                  <span className="font-semibold text-gray-800 dark:text-white">{product.stock} units</span>
                </div>
                <div className="flex justify-between py-2 border-b border-gray-200 dark:border-gray-600">
                  <span className="text-gray-600 dark:text-gray-400">Shelf Life:</span>
